{
    public bool $readOnlyMatching=false;
    private function checkSql(string $sql):void{if($this->readOnlyMatching&&!preg_match('/\A\s*SELECT\b/i',$sql))throw new RuntimeException('MATCH_TEST_WRITE_FORBIDDEN');}
    public function prepare(string $query,array $options=[]):PDOStatement|false{$this->checkSql($query);return parent::prepare($query,$options);}
    public function query(string $query,?int $fetchMode=null,mixed ...$fetchModeArgs):PDOStatement|false{$this->checkSql($query);return $fetchMode===null?parent::query($query):parent::query($query,$fetchMode,...$fetchModeArgs);}
    public function exec(string $statement):int|false{$this->checkSql($statement);return parent::exec($statement);}
}
